function scaleStage(){
  const r=$('#cdqPcV16'),stage=$('.pc16-stage',r);if(!r||!stage)return;
  const BASE_W=1536,BASE_H=864;
  const v=pc16ViewportV21_65();

  // Keep the width full, but deliberately use only 94% of the visible height.
  // This fixes the PC dashboard looking too tall while preserving the width.
  const scaleX=Math.max(.10,Math.min(5,v.w/BASE_W));
  const scaleY=Math.max(.10,Math.min(5,(v.h*.94)/BASE_H));

  r.style.setProperty('left','0px','important');
  r.style.setProperty('top',v.oy+'px','important');
  r.style.setProperty('width',v.w+'px','important');
  r.style.setProperty('height',v.h+'px','important');
  r.style.setProperty('max-width','none','important');
  r.style.setProperty('max-height','none','important');
  r.style.setProperty('margin','0','important');
  r.style.setProperty('overflow','hidden','important');
  r.style.background='#020911';

  stage.style.setProperty('left','0px','important');
  stage.style.setProperty('top','0px','important');
  stage.style.setProperty('width',BASE_W+'px','important');
  stage.style.setProperty('height',BASE_H+'px','important');
  stage.style.setProperty('transform-origin','0 0','important');
  stage.style.setProperty('transform','scale('+scaleX+','+scaleY+')','important');

  const sig=v.w+'x'+v.h+'@'+scaleX.toFixed(4)+'x'+scaleY.toFixed(4);
  if(pc16LastFitV21_65!==sig){
    pc16LastFitV21_65=sig;
    stage.dataset.fit=sig;
    stage.dataset.viewport=v.w+'x'+v.h;
  }
}

